{
 "contract_type": "saas",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Bluepeak Systems LLC"],
   "quote": "between Northwind Labs, Inc. (\"Northwind\") and Bluepeak Systems LLC (\"Bluepeak\")"
  },
  "counterparty": {
   "value": "Bluepeak Systems LLC",
   "quote": "Bluepeak Systems LLC (\"Bluepeak\")"
  },
  "effective_date": {
   "value": "2025-03-11",
   "quote": "is effective as of 11th day of March, 2025"
  },
  "term_months": {
   "value": 36,
   "quote": "continue for a period of thirty-six (36) months"
  },
  "auto_renewal": {
   "value": true,
   "quote": "the Agreement renews automatically for additional twelve-month terms"
  },
  "renewal_notice_days": {
   "value": 30,
   "quote": "a Party must notify the other no later than thirty (30) days before the renewal date"
  },
  "governing_law": {
   "value": "Texas",
   "quote": "the laws of the State of Texas"
  },
  "liability_cap": {
   "value": "fees_12m",
   "quote": "EXCEED THE TOTAL FEES PAID OR PAYABLE IN THE TWELVE (12) MONTHS PRECEDING THE EVENT GIVING RISE TO THE CLAIM"
  },
  "payment_terms_days": {
   "value": 30,
   "quote": "Invoices are due 30 days after the invoice date."
  },
  "contract_value": {
   "value": 96000,
   "quote": "The subscription fee is $96,000 per year, invoiced annually in advance."
  },
  "termination_for_convenience": {
   "value": false,
   "quote": "Either Party may terminate this Agreement only upon a material breach by the other Party that remains uncured thirty (30) days after written notice."
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  },
  {
   "name": "Jordan Alvarez",
   "email": "jordan.alvarez@bluepeak.example",
   "title": "VP Operations",
   "party": "Bluepeak Systems LLC"
  }
 ],
 "risks": [
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "Northwind is locked in for 36 months and can only exit for uncured material breach, so it must pay the full fees even if the platform stops being useful.",
   "quote": "Either Party may terminate this Agreement only upon a material breach by the other Party that remains uncured thirty (30) days after written notice."
  },
  {
   "id": "auto_renewal_opt_out_window",
   "severity": "medium",
   "message": "The agreement renews automatically for 12-month terms unless notice is given at least 30 days before the renewal date, so a missed deadline commits Northwind to another year at about $96,000.",
   "quote": "the Agreement renews automatically for additional twelve-month terms; to opt out, a Party must notify the other no later than thirty (30) days before the renewal date."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "medium",
   "message": "The agreement has no confidentiality clause, so Northwind's data and information shared with Bluepeak have no contractual protection.",
   "quote": "Each Party represents that it has full power and authority to enter into this Agreement."
  },
  {
   "id": "annual_prepayment",
   "severity": "low",
   "message": "Fees are invoiced a year in advance, which ties up cash and leaves no refund mechanism if the service is terminated early.",
   "quote": "invoiced annually in advance"
  },
  {
   "id": "liability_cap_tied_to_fees",
   "severity": "low",
   "message": "Liability for both parties is capped at 12 months of fees, which limits Northwind's recovery for data loss or serious service failures.",
   "quote": "IN NO EVENT SHALL EITHER PARTY'S AGGREGATE LIABILITY ARISING OUT OF THIS AGREEMENT EXCEED THE TOTAL FEES PAID OR PAYABLE IN THE TWELVE (12) MONTHS PRECEDING THE EVENT GIVING RISE TO THE CLAIM."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a SaaS subscription between Northwind Labs, Inc. and Bluepeak Systems LLC, effective March 11, 2025, running 36 months at $96,000 per year and auto-renewing for 12-month terms unless notice is given 30 days before renewal. It is governed by Texas law, caps liability at 12 months of fees, allows termination only for uncured material breach, and has no confidentiality clause."
}
